/*
 * A170328  Number of reduced words of length n in Coxeter group on 31
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^42 = I.
 * https://oeis.org/A170328
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0) = 1 For 1 ≤ n ≤ 41: a(n) = 2 + 29 * (a(n-1) + a(n-2) + … +
 *            a(0)) For n ≥ 42: a(n) = 29 * (a(n-1) + a(n-2) + … + a(n-41)) -
 *            435 * a(n-42) (The numbers are generated by the rational
 *            generating function shown in the OEIS entry for A170328.)
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 6, u64 n <= 13, u128 n <= 15,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static cache of already computed terms.  cache_len stores the
       number of terms currently stored (the last valid index + 1). */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;   /* number of elements stored */

    /* Ensure the cache is large enough for indexes up to n. */
    if (n >= cache_len) {
        size_t new_len = (size_t)n + 1;          /* need space for 0…n */
        seq_t *tmp = (seq_t *)realloc(cache, new_len * sizeof(seq_t));
        if (!tmp) return (seq_t)0;               /* allocation failed */
        cache = tmp;
        /* Fill the new terms.  We start from the first missing index. */
        for (size_t i = cache_len; i <= (size_t)n; ++i) {
            if (i == 0) {
                cache[0] = (seq_t)1;
            } else if (i <= 41) {
                seq_t sum = 0;
                for (size_t k = 1; k <= i; ++k) {
                    sum += cache[i - k] * ((seq_t)29);
                }
                cache[i] = (seq_t)2 + sum;
            } else { /* i >= 42 */
                seq_t sum = 0;
                for (size_t k = 1; k <= 41; ++k) {
                    sum += cache[i - k] * ((seq_t)29);
                }
                cache[i] = sum - ((seq_t)435 * cache[i - 42]);
            }
        }
        cache_len = new_len;
    }

    return cache[(size_t)n];
}
